   208                        aom_malloc(sizeof(*(*cdef_row_mt)[row_idx].row_cond_)));
   209        pthread_cond_init((*cdef_row_mt)[row_idx].row_cond_, NULL);
   210
   211        (*cdef_row_mt)[row_idx].is_row_done = 0;
   212      }
   213  #endif  // CONFIG_MULTITHREAD
   214    }
   215  }
